/** Units as quoted in India. Quantities are stored in an SI base and converted. */
export type TradeUnit = 'SQFT' | 'SQM' | 'RFT' | 'RMT' | 'POINT' | 'NOS' | 'SET' | 'LS';

export type Trade =
  | 'CIVIL' | 'WATERPROOFING' | 'FALSE_CEILING' | 'ELECTRICAL' | 'PLUMBING'
  | 'FLOORING' | 'PAINTING' | 'CARPENTRY' | 'MODULAR_KITCHEN' | 'WARDROBE'
  | 'GLASS_METAL' | 'LOOSE_FURNITURE' | 'LIGHTING' | 'APPLIANCES' | 'SANITARY'
  | 'DECOR' | 'DESIGN_FEE' | 'MISC';

export type SupplyNature = 'GOODS' | 'SERVICE' | 'WORKS_CONTRACT';

/**
 * How a quantity is derived. GEOMETRY lines recompute automatically when the
 * plan changes; MANUAL lines keep the typed quantity.
 */
export type QuantityRule =
  | { kind: 'FLOOR_AREA' }                                  // room floor m²
  | { kind: 'CEILING_AREA' }                                // room ceiling m²
  | { kind: 'WALL_AREA'; deductOpenings: boolean }          // room's inner wall faces m²
  | { kind: 'PERIMETER'; deductDoors: boolean }             // skirting/cornice, m
  | { kind: 'COUNT_OPENINGS'; of: 'DOOR' | 'WINDOW' }       // nos
  | { kind: 'POINTS_PER_ROOM'; byRoomKind: Record<string, number>; fallback: number } // electrical
  | { kind: 'FIXED'; quantity: number }                     // e.g. LS = 1
  | { kind: 'MANUAL' };

export interface RateSource {
  name: string;
  url?: string;
  asOf: string;
  confidence: 'LOW' | 'MEDIUM' | 'HIGH';
}

export interface RateCardEntry {
  id: string;                      // stable, e.g. 'FC-GYP-PLAIN'
  trade: Trade;
  description: string;             // as printed on the quote
  unit: TradeUnit;
  materialRate: Paise;             // per unit, ex-GST
  labourRate: Paise;               // per unit, ex-GST
  hsnSac: string;                  // e.g. '9954' works contract, '998391' design, '9403' furniture
  gstRatePct: number;              // 18 by default
  supplyNature: SupplyNature;
  /** Default quantity rule when this entry is added to a room. */
  defaultRule: QuantityRule;
  /** Room kinds (from shared/rules inferRoomKind) this applies to by default; empty = manual only. */
  autoApplyTo?: string[];
  wastagePct?: number;
  makeList?: string[];             // approved brands, printed in the make list
  inclusions?: string[];
  exclusions?: string[];
  tier?: 'BUDGET' | 'STANDARD' | 'PREMIUM' | 'LUXURY';
  source: RateSource;
  /**
   * Flooring entries only: auto-apply only to rooms whose floor material is of
   * one of these classes ('TILE' | 'STONE' | 'WOOD' | 'LAMINATE' | 'CONCRETE' |
   * 'CARPET', see trades.ts floorFinishOf). Absent = any floor.
   */
  floorFinishes?: string[];
}

export interface RateCard {
  id: string;
  name: string;                    // 'Metro mid-segment 2026 (default)'
  city?: string;
  currency: 'INR';
  /** What the card is and how far to trust it, shown in the rate-card editor. */
  description?: string;
  entries: RateCardEntry[];
}

/** A studio's changes on top of a base card: override rates or add entries. */
export interface RateCardOverrides {
  baseCardId: string;
  overrides: Record<string, Partial<Pick<RateCardEntry, 'materialRate' | 'labourRate' | 'description' | 'makeList' | 'hsnSac' | 'gstRatePct'>>>;
  added: RateCardEntry[];
  disabled: string[];
}

