export type DocType = 'QUOTATION' | 'PROFORMA' | 'TAX_INVOICE' | 'BILL_OF_SUPPLY' | 'PLAIN_INVOICE' | 'VARIATION_ORDER';

export interface TradeLineItem {
  id: string;
  /** '3.04' — section.sequence, stable across versions so contracts can cite it. */
  lineNo: string;
  roomId?: string;                 // absent = whole-house line
  trade: Trade;
  rateCardEntryId?: string;
  description: string;
  spec?: { brand?: string; grade?: string; finish?: string };
  unit: TradeUnit;
  rule: QuantityRule;
  /** SI base (m², m, count). Recomputed from `rule` unless MANUAL. */
  quantityBase: number;
  /** In `unit`, rounded: sq ft/rft 2 dp, counts up to an integer, LS = 1. */
  quantityDisplay: number;
  /** How the quantity was derived, e.g. 'Living walls 22.00 m run × height = 59.40 m² − 4 openings …'. */
  formula?: string;
  materialRate: Paise;
  labourRate: Paise;
  /** Internal only — never printed. The printed rate already includes it. */
  markupPct: number;
  discountPct: number;
  amount: Paise;
  hsnSac: string;
  gstRatePct: number;
  supplyNature: SupplyNature;
  clientSupplied: boolean;         // client buys material → only labour billed
  optional: boolean;               // shown but excluded from totals
}

export type QuoteLine =
  | ({ kind: 'TRADE' } & TradeLineItem)
  | { kind: 'MODULAR'; id: string; lineNo: string; roomId: string; description: string; item: ModularItem; breakdown: ModularBreakdown; amount: Paise; hsnSac: string; gstRatePct: number; optional: boolean };

export interface TaxLine {
  hsnSac: string;                  // truncated to 4 or 6 digits by turnover band
  taxableValue: Paise;
  ratePct: number;
  cgst: Paise; sgst: Paise; igst: Paise;
}

export interface PaymentMilestone {
  id: string;
  label: string;                   // 'Booking', 'Design sign-off', 'Before dispatch', 'Handover'
  pct: number;                     // of grand total; milestones sum to 100
  amount: Paise;                   // derived
  trigger: 'ON_SIGNING' | 'ON_APPROVAL' | 'ON_DELIVERY' | 'ON_HANDOVER';
}

export interface Approval {
  id: string;
  decision: 'APPROVED' | 'CHANGES_REQUESTED';
  byName: string;
  byContact: string;               // phone or email, as typed by the client
  method: 'PORTAL_LINK';
  at: string;
  /** Hash of the document's canonical JSON at the time of approval. */
  documentHash: string;
  comment?: string;
  userAgent?: string;
}

export type QuoteStatus = 'DRAFT' | 'ISSUED' | 'APPROVED' | 'CHANGES_REQUESTED' | 'SUPERSEDED' | 'CANCELLED';

export interface QuotationDocument {
  id: string;
  projectId: string;
  docType: DocType;
  /** Assigned on issue: '<prefix>/Q/26-27/0042', ≤ 16 chars per GST Rule 46 where possible. */
  number?: string;
  version: number;
  supersedesId?: string;
  /** For a VARIATION_ORDER: the approved quote it amends. */
  amendsId?: string;
  status: QuoteStatus;
  issueDate?: string;
  validUntil?: string;
  financialYear: string;           // '2026-27'
  supplier: StudioProfile;         // snapshot at issue — immutable afterwards
  recipient: Party;
  siteAddress: Address;            // place of supply for design and works services
  placeOfSupplyStateCode: string;
  isInterState: boolean;
  areaBasis?: { kind: 'CARPET' | 'BUILT_UP' | 'SUPER_BUILT_UP'; sqft: number };
  view: 'ROOM_WISE' | 'TRADE_WISE';
  sections: Array<{ id: string; title: string; lines: QuoteLine[]; subtotal: Paise }>;
  designFee?: { basis: 'PCT_OF_PROJECT' | 'PER_SQFT' | 'LUMP_SUM'; value: number; amount: Paise; sac: '998391'; gstRatePct: number };
  discount?: { label: string; amount: Paise };
  taxableValue: Paise;
  taxLines: TaxLine[];
  totalTax: Paise;
  roundOff: Paise;
  grandTotal: Paise;
  amountInWords: string;           // 'Rupees Twelve Lakh Thirty-Four Thousand … Only'
  paymentSchedule: PaymentMilestone[];
  makeList: Array<{ category: string; brands: string[] }>;
  inclusions: string[];
  exclusions: string[];            // required — the most common root of disputes
  terms: string[];
  compositionDeclaration?: string;
  /** Plan version the quantities were derived from (cloud project version). */
  projectVersion?: number;
  approvals: Approval[];
  lockedAt?: string;
  /** Free tier: shown on the document and the share link. */
  watermark: boolean;
  /** SHA-256 hex of canonicalJson(doc without approvals/status/lockedAt/hash). */
  hash?: string;
  /** Advisory problems found by buildQuote (missing exclusions, lines on deleted rooms …). Not hashed. */
  warnings?: string[];
}

/** Inputs the quote builder needs beyond the plan. */
export interface QuoteDraftInput {
  project: Project;
  rateCard: RateCard;
  overrides?: RateCardOverrides;
  studio: StudioProfile;
  recipient: Party;
  siteAddress: Address;
  lines: QuoteLine[];              // editable; GEOMETRY lines are re-derived from the plan
  view: QuotationDocument['view'];
  designFee?: { basis: 'PCT_OF_PROJECT' | 'PER_SQFT' | 'LUMP_SUM'; value: number };
  discount?: { label: string; amount: Paise };
  milestones: Array<{ label: string; pct: number; trigger: PaymentMilestone['trigger'] }>;
  makeList: QuotationDocument['makeList'];
  inclusions: string[];
  exclusions: string[];
  terms: string[];
  areaBasis?: QuotationDocument['areaBasis'];
  docType: DocType;
  issueDate: string;               // ISO date
  validityDays: number;
  watermark: boolean;
}

