export type PlanId = 'FREE' | 'PROJECT_PASS' | 'SOLO' | 'STUDIO' | 'BUSINESS';

export interface Entitlements {
  plan: PlanId;
  /** Projects the account may own at once; null = unlimited. */
  maxActiveProjects: number | null;
  /** Project ids unlocked by Project Pass purchases. */
  passProjectIds: string[];
  brandedQuotes: boolean;          // false → watermark, and studio logo/brand colour not shown
  /** Document types the account may issue. FREE: ['QUOTATION'] only. */
  docTypes: DocType[];
  clientApprovals: boolean;        // true on every plan — watermarked approvals are the growth loop
  rateCards: boolean;
  modular: boolean;
  variationOrders: boolean;
  seats: number;
  historyDays: number | null;
  /** When a paid period ends; null for FREE. */
  currentPeriodEnd: string | null;
}

